<section class="section-pad container" id="pricing"><div class="section-head"><span class="eyebrow">SIMPLE PLANS. SERIOUS POSSIBILITIES.</span><h2>A little start. A lot of potential.</h2><p>Choose the workspace that fits your ambition. Prices in INR, billed monthly.</p></div><div class="grid grid-4"><?php try{$plans=rows('SELECT * FROM plans WHERE active=1 ORDER BY price');}catch(Throwable){$plans=[['name'=>'Free','price'=>0,'websites'=>1,'keywords'=>50,'crawl_pages'=>100,'reports'=>1],['name'=>'Starter','price'=>199900,'websites'=>3,'keywords'=>250,'crawl_pages'=>1000,'reports'=>10],['name'=>'Growth','price'=>599900,'websites'=>10,'keywords'=>1000,'crawl_pages'=>5000,'reports'=>-1],['name'=>'Agency','price'=>1499900,'websites'=>50,'keywords'=>5000,'crawl_pages'=>25000,'reports'=>-1]];}foreach($plans as $p):?><div class="card pricing-card <?=$p['name']==='Growth'?'featured':''?>"><?php if($p['name']==='Growth'):?><span class="popular">ROOM TO GROW</span><?php endif;?><h3><?=e($p['name'])?></h3><div class="price"><?=money((int)$p['price'])?><small> / month</small></div><ul><li><?=e($p['websites'])?> websites</li><li><?=number_format($p['keywords'])?> tracked keywords</li><li><?=number_format($p['crawl_pages'])?> pages per crawl</li><li><?=$p['reports']<0?'Unlimited':e($p['reports'])?> monthly reports</li><?php if($p['name']==='Agency'):?><li>Team access & white-label reports</li><?php endif;?></ul><a class="button full <?=$p['name']==='Growth'?'':'secondary'?>" href="<?=url(current_user()?'/billing':'/register')?>"><?=$p['price']?'Choose '.$p['name']:'Start free'?> â†—</a></div><?php endforeach;?></div></section>
